    <svg
      viewBox="0 0 24 24"
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
      className={cn(className, "h-6")}
      {...props}
    >
      {CLAUDE_BLADES.map((deg) => (
        <path
          key={deg}
          d="M11.4 12 L10.7 4.1 Q12 2 13.3 4.1 L12.6 12 Z"
          transform={`rotate(${deg} 12 12)`}
        />
      ))}
    </svg>
